verify "$TMPD/a1" "${NEW_ADD[1]}" "frontend/src/components/wallet/AddCredits.tsx"

grep -q 'export async function claimTopup' "$TMPD/a0" || die "topup.ts payload is wrong. Aborting."
grep -q 'primary_fungible_store::transfer' "$TMPD/a1" || die "frontend/src/components/wallet/AddCredits.tsx payload is wrong. Aborting."
grep -q -- '025_topups' "$TMPD/m1" || die "migrations.ts payload is wrong. Aborting."
grep -q -- '024_credits' "$TMPD/m1" || die "migrations.ts payload lost 16a. Aborting."
grep -q -- 'claimTopup' "$TMPD/m3" || die "credits route payload is wrong. Aborting."
grep -q -- '"manualTitle"' "$TMPD/m10" || die "en.json payload is wrong. Aborting."
grep -q -- '"notCharging"' "$TMPD/m10" || die "en.json payload lost 16a. Aborting."
grep -q -- 'AddCredits' "$TMPD/m6" || die "wallet page payload is wrong. Aborting."
say "16 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in ${ADD[@]+"${ADD[@]}"}; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in ${ADD[@]+"${ADD[@]}"}; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in ${ADD[@]+"${ADD[@]}"}; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Part 16b (adding credits with ShelbyUSD)."
say "Migration 025_topups runs by itself when the backend starts."
say "Top ups stay off until TOPUP_TREASURY_ADDRESS is set on Render (the treasury's public address)."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit) && (cd frontend && npx tsc --noEmit) && (cd dashboard && npx tsc --noEmit)"
say "Undo: ./vm_credits_b.sh --revert"
